.grid {
  display: grid;

  /* Three equal columns */
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-columns: repeat(3, 1fr);  /* same thing */

  /* Mixed columns: sidebar + main */
  grid-template-columns: 240px 1fr;

  /* Responsive: as many 200px+ columns as fit */
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));

  /* Rows */
  grid-template-rows: auto 1fr auto;  /* header | content | footer */

  gap: 24px;             /* space between all tracks */
  gap: 16px 24px;        /* row-gap column-gap */
}

.layout {
  display: grid;
  grid-template-areas:
    'header  header '
    'sidebar main   '
    'footer  footer ';
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
  gap: 0;
}

header  { grid-area: header; }
.sidebar { grid-area: sidebar; }
main    { grid-area: main; }
footer  { grid-area: footer; }

/* Span 2 columns */
.wide { grid-column: span 2; }

/* Span 2 rows */
.tall { grid-row: span 2; }

/* Explicit placement: start-line / end-line */
.feature {
  grid-column: 1 / 3;   /* from column line 1 to line 3 */
  grid-row:    1 / 2;
}
